\label{lem:alg1}
Let $\varepsilon>0$ and let $\mathfrak{b},\mathfrak{c}$ be integral ideals.
Then 
\begin{enumerate}
\item[(i)]
there exists $\alpha\in \mathfrak{b}$ such that $\mathrm{ord}_{\mathfrak{p}}(\alpha)=\mathrm{ord}_\mathfrak{p}(\mathfrak{b})$ for every prime ideal
$\mathfrak{p}\mid \mathfrak{c}$;
\item[(ii)]
there exists $\alpha\in \mathfrak{b}$ and an unramified prime ideal $\mathfrak{p}$ coprime to
$\mathfrak{b}^\tau$ for all $\tau\in \operatorname{Gal}(K/\mathbb{Q})$, 
with $\operatorname{N}\mathfrak{p} \ll (\operatorname{N} \mathfrak{b})^{\varepsilon}$, 
 such that $(\alpha)=\mathfrak{b}\mathfrak{p}$.
\end{enumerate}

\label{lem:orthogonal}
Let $\mathfrak{b}\subsetneq \mathfrak{o}$ be a non-zero ideal. Then there exists $\gamma\in \mathfrak{F}(\mathfrak{b})$
such that $\psi(\gamma\cdot)$ defines a non-trivial primitive additive character modulo $\mathfrak{b}$.

\label{lem:poisson}
We have
$$
N_{W}(F,N;P)=
\frac{c_{P}P^{(n-2)d}}{D_{K}^{n/2}} 
\sum_{\operatorname{N}\mathfrak{b}\ll P^d} 
\sum_{\substack{\mathbf{m}\in \widehat{{{}^{{G}}\mathfrak{b}}  }^n}}
(\operatorname{N} {{}^{{G}}\mathfrak{b}}  )^{-n}
S_\mathfrak{b}  (N;\mathbf{m})
I_\mathfrak{b}  (N/P^2;P\mathbf{m}),
$$
where the sum over $\mathfrak{b}$ is over non-zero integral ideals and
\begin{align*}
S_\mathfrak{b}  (N;\mathbf{m})
&=\sideset{}{^*}\sum_{\sigma\,(\operatorname{mod}{\mathfrak{b}})}\sum_{\mathbf{a}\,(\operatorname{mod}{{{}^{{G}}\mathfrak{b}} })}\sigma(F(\mathbf{a})-N)\psi(\mathbf{m}. \mathbf{a}),\\
I_\mathfrak{b}  (t;\mathbf{k})
&=
\int_{ V^{n}}W(\mathbf{x})h\left(\frac{\operatorname{N} \mathfrak{b}}{P^d}  ,|\operatorname{Nm}(F(\mathbf{x})-t)|\right)\psi\left(-\mathbf{k}.\mathbf{x} \right)\mathrm{d}\mathbf{x}.
\end{align*}

\label{lem:S-zero}
We have $S_\mathfrak{b}  (N;\mathbf{m})=0$ unless 
$\mathbf{m}.\mathbf{h}\in \mathfrak{d}^{-1}$ for all $\mathbf{h}\in \mathscr{H}_\mathfrak{b}$.

\label{lem:main_term}
Let $\varepsilon>0$. Then, for any $A\geqslant 1$, we have 
\begin{align*}
M(P)=~&
\frac{P^{(n-2)d} }{D_{K}^{n-1/2}}  
\sum_{\substack{0\neq \mathfrak{b}\subset \mathfrak{o}\\ \operatorname{N}\mathfrak{b}\ll P^d}}
(\operatorname{N} {{}^{{G}}\mathfrak{b}}  )^{-n}
S_\mathfrak{b}  (N;\0)
\left(\sigma_\infty(N/P^2)
+O_A\left(\left(\frac{\operatorname{N}\mathfrak{b}}{P^d}\right)^A\right)\right) \\
&\qquad
+O_A(P^{-A}),
\end{align*}
where
 $\sigma_\infty(N/P^2)>0$ is  given by \eqref{eq:sig-infinity}.

\label{lem:b=p}
Let $\varepsilon>0$. 
Let $\mathfrak{b}\subset \mathfrak{o}$ be a non-zero ideal and  let 
 $\mathbf{m}\in \widehat{{}^{{G}}\mathfrak{b}}^n$. 
Then 
$$
S_\mathfrak{b}  (N;\mathbf{m})\ll 
  (\operatorname{N}\mathfrak{b})^{\frac{1}{2}-(n-m)/2+\varepsilon}  
(\operatorname{N} {{}^{{G}}\mathfrak{b}})^{n-m/2} 
\prod_{
\substack{
\mathfrak{p} \mid (\mathfrak{b},N)\\ 
\operatorname{N}\mathfrak{p}
 \| \operatorname{N}\mathfrak{b}\\
\mathrm{ord}_\mathfrak{p}(G(\mathbf{m}))\geqslant -1\\
}
}(\operatorname{N}\mathfrak{p})^{\frac{1}{2}}
\hspace{0.2cm}
\prod_{
\substack{p^k\| \operatorname{N} \mathfrak{b} \\ k\geqslant 2}}
p^{\frac{k}{2}},
$$
where $G$ is given by 
\eqref{eq:def-G}.

\label{lem:tornado}
Let 
$$
L_i(u)=a_iu+\tau^{-1}(b_iu),
$$
for $1\leqslant i\leqslant m$. 
Then, for any $\varepsilon>0$,  $K(u,P\mathbf{m})$ is essentially supported on the set of $u$ and $\mathbf{m}$ for which 
\begin{equation}\label{eq:mot}
|m_i^{(l)}| \ll 
\begin{cases} 
P^{-1+\varepsilon} |\rho_l(L_i(u))| &\text{ if $i\leqslant m$,}\\
P^{-1+\varepsilon} |u_l| &\text{ if $i> m$,}
\end{cases}
\end{equation}
for $1\leqslant l\leqslant d$. Moreover, we have 
$$
K(u,P\mathbf{m})\ll   \frac{1}{\sqrt{\mathfrak{H}(L_1(u))\cdots 
 \mathfrak{H}(L_m(u))
 \mathfrak{H}(u)^{n-m}}}.
$$

\label{lem:I-theta}
We have 
\begin{align*}
I(X,Y)\ll ~&
P^\varepsilon (P^{-d} Y)^{m}
\left( \left(\frac{P^{d}}{X}\right)^{3m/2-n/2+1}+1\right)\\
&\quad +
c_YP^\varepsilon \left( 
\frac{P^{d(m/2-n/2+1)}Y^{m-1}}{X^{3m/2-n/2}}+
 \frac{Y}{P^d}\right)+P^\varepsilon \left(\frac{P^d}{X}\right)^{1-(n-m)/2}
 \hspace{-1cm},
 \end{align*}
where
$$
c_Y=\begin{cases}
1 &\text{ if $Y\leqslant P^{d}$,}\\
0 & \text{ otherwise}.
\end{cases}
$$
